// eep-modtest74b.js - mod test 74 repeated with the 5% refugee host limit SAVED through the settings store. The pass re-reads saved settings into CONFIG every turn (emigration-main.js refreshSettings), so mod test 74 ran at 0.1 after its first pass. Restores the default on finish. Markers stay "modtest74" (run-probe matches digits only).
// settlements), CONFIG at its shipped defaults (every layer on), TURNS script-ended turns (one-turn Autoplay
// fallback when blocked, which activates the local turn and runs the pass). CONTROL = true (eep-modtest58.js,
// generated by sed) runs the identical loop with the mod's pass switched off (turnInterval 99999), so the two
// logs compare the same save with and without emigration. Every 10 turns and at FINAL: major-civ population
// and settlement counts, world share of the largest civ, treasury, the mod's counters, enclaves, refugees
// resettling, the smallest settlement, and the largest one-turn population drop of any settlement.
import { CONFIG, CONFIG_DEFAULTS } from "/emigration/ui/emigration-config.js";
import { loadState } from "/emigration/ui/emigration-state.js";
import { setTunable, resetTunable, getTunable } from "/emigration/ui/emigration-settings.js";
import { collectCitySignals } from "/emigration/ui/emigration-cities.js";
import { telemetryCounters } from "/emigration/ui/emigration-telemetry.js";
import { allQuarterEntries, allCandidacyEntries } from "/emigration/ui/emigration-quarter-state.js";
import { refugeePoolTotalForOwner } from "/emigration/ui/emigration-refugee-pool.js";

const CONTROL = false;
const TURNS = 30;
const TAG = "[EmigTest]";
function emit(m) { try { console.error(TAG + " " + m); } catch (_) {} }
function J(o) { try { return JSON.stringify(o); } catch (e) { return "unserializable:" + e; } }
function safe(fn, fb) { try { return fn(); } catch (e) { return fb === undefined ? ("ERR:" + e) : fb; } }

let local = -1, n = 0, endTurnTimer = null, blockedTries = 0, fallbacks = 0, done = false;

// Pop-ups. The shipped "Ask me" arrival placement and the rare refugee decision open dialogs that wait for a
// person (run 1 of this test stalled on them until the user clicked through by hand). The run answers them as an
// unattended player would: arrivals "Let the city settle them", refugees "Welcome them in"; any other dialog takes
// its last button. One answer per tick, each logged.
const ANSWERS = [/Let the city settle them/i, /Welcome them in/i];
let answered = 0;
function answerDialogs() {
  if (done) return;
  safe(() => {
    for (const d of Array.from(document.querySelectorAll("screen-dialog-box"))) {
      const buttons = Array.from(d.querySelectorAll("fxs-button, fxs-hero-button"));
      if (!buttons.length) continue;
      const label = (b) => String(b.getAttribute("caption") || b.textContent || "").trim();
      let pick = null;
      for (const re of ANSWERS) { pick = buttons.find((b) => re.test(label(b))); if (pick) break; }
      if (!pick) pick = buttons[buttons.length - 1];
      const title = safe(() => d.querySelector("fxs-header").getAttribute("title"), "?");
      pick.dispatchEvent(new CustomEvent("action-activate", { bubbles: true }));
      answered++;
      if (answered <= 40 || answered % 25 === 0) emit("DIALOG #" + answered + " " + J(title) + " -> " + J(label(pick)));
      break;
    }
  });
}
setInterval(answerDialogs, 1500);
let first = null;
/** @type {Map<string, number>} */
const prevPop = new Map();
let maxDrop = { pts: 0, city: "", turn: 0 };

function snapshot() {
  const sigs = (safe(() => collectCitySignals(), []) || []).filter((s) => !s.isCityState);
  const civs = {};
  let world = 0, minPop = Infinity, minCity = "";
  for (const s of sigs) {
    const o = String(s.owner);
    const c = civs[o] || (civs[o] = { pop: 0, settlements: 0 });
    c.pop += Number(s.population) || 0;
    c.settlements++;
    world += Number(s.population) || 0;
    if ((Number(s.population) || 0) < minPop) { minPop = Number(s.population) || 0; minCity = safe(() => Locale.compose(s.city.name), "?"); }
  }
  let top = 0, negGold = 0, pool = 0;
  for (const o of Object.keys(civs)) {
    top = Math.max(top, civs[o].pop);
    const gold = safe(() => Players.get(Number(o)).Treasury.goldBalance, null);
    civs[o].gold = typeof gold === "number" ? Math.round(gold) : null;
    if (typeof gold === "number" && gold < 0) negGold++;
    civs[o].resettling = Number(safe(() => refugeePoolTotalForOwner(Number(o)), 0)) || 0;
    pool += civs[o].resettling;
  }
  return {
    turn: safe(() => Game.turn), world: Math.round(world), settlements: sigs.length,
    topShare: world > 0 ? Math.round((top / world) * 1000) / 10 : 0, minPop, minCity, negGold, resettling: pool,
    enclaves: safe(() => allQuarterEntries().length, 0), candidacies: safe(() => allCandidacyEntries().length, 0),
    counters: safe(() => telemetryCounters(), {}), civs,
    cfg: { poachBlock: CONFIG.poachBlock, crisisEscapeBonus: CONFIG.crisisEscapeBonus, antiDrainWeight: CONFIG.antiDrainWeight, refugeeHostCapPct: CONFIG.refugeeHostCapPct, askRefugees: CONFIG.arrivalAskRefugees, askMigrants: CONFIG.arrivalAskMigrants }
  };
}

function trackDrops() {
  for (const s of safe(() => collectCitySignals(), []) || []) {
    const p = Number(s.population) || 0;
    const was = prevPop.get(s.key);
    if (typeof was === "number" && was - p > maxDrop.pts) maxDrop = { pts: was - p, city: safe(() => Locale.compose(s.city.name), "?"), turn: safe(() => Game.turn, 0) };
    prevPop.set(s.key, p);
  }
}

function finish(why) {
  if (done) return;
  done = true;
  safe(() => resetTunable("refugeeHostCapPct"));
  const last = snapshot();
  const ratios = {};
  for (const o of Object.keys(first.civs)) {
    const a = first.civs[o].pop, b = last.civs[o] ? last.civs[o].pop : 0;
    ratios[o] = a > 0 ? Math.round((b / a) * 100) / 100 : null;
  }
  emit("FINAL (" + why + ") " + J(last));
  emit("SUMMARY control=" + CONTROL + " turns=" + n + " turn=" + first.turn + "->" + last.turn + " world=" + first.world + "->" + last.world +
    " settlements=" + first.settlements + "->" + last.settlements + " topShare=" + first.topShare + "->" + last.topShare +
    " civPopRatio=" + J(ratios) + " maxOneTurnDrop=" + J(maxDrop) + " minPop=" + last.minPop + " negGold=" + last.negGold +
    " resettling=" + last.resettling + " enclaves=" + first.enclaves + "->" + last.enclaves + " counters=" + J(last.counters) +
    " autoplayFallbacks=" + fallbacks + " dialogsAnswered=" + answered);
  emit("DONE modtest74 finished");
}

function run() {
  local = GameContext.localPlayerID;
  Object.assign(CONFIG, CONFIG_DEFAULTS);
  setTunable("refugeeHostCapPct", 0.05); // saved, so the per-pass settings refresh keeps it
  if (CONTROL) CONFIG.turnInterval = 99999;
  first = snapshot();
  trackDrops();
  emit("HOSTCAP saved=" + safe(() => getTunable("refugeeHostCapPct")) + " config=" + CONFIG.refugeeHostCapPct);
  emit("START control=" + CONTROL + " " + J(first));
  setTimeout(endTurn, 2000);
}

function endTurn() {
  if (done) return;
  try {
    const me = Players.get(local);
    if (!me.isTurnActive || GameContext.hasSentTurnComplete()) return;
    const b = String(Game.Notifications.getEndTurnBlockingType(local));
    if (b !== String(EndTurnBlockingTypes.NONE)) {
      blockedTries++;
      if (blockedTries >= 3 && typeof Autoplay !== "undefined") {
        fallbacks++;
        safe(() => { Autoplay.setTurns(1); Autoplay.setReturnAsPlayer(local); Autoplay.setObserveAsPlayer(local); Autoplay.setActive(true); });
        blockedTries = 0; endTurnTimer = setTimeout(endTurn, 30000); return;
      }
      endTurnTimer = setTimeout(endTurn, 4000); return;
    }
    safe(() => UI.Player.deselectAllUnits()); GameContext.sendTurnComplete();
  } catch (e) { emit("ENDTURN threw " + e); }
  endTurnTimer = setTimeout(() => { if (safe(() => Players.get(local).isTurnActive, false) && !GameContext.hasSentTurnComplete()) endTurn(); }, 12000);
}

engine.on("PlayerTurnActivated", (d) => {
  const who = d && (d.player ?? d.Player);
  if (who !== GameContext.localPlayerID || local < 0 || done) return;
  if (endTurnTimer) { clearTimeout(endTurnTimer); endTurnTimer = null; }
  n++; blockedTries = 0;
  setTimeout(() => {
    trackDrops();
    if (n % 10 === 0) emit("T n=" + n + " fallbacks=" + fallbacks + " " + J(snapshot()));
    if (n % 5 === 0) emit("INTAKE n=" + n + " turn=" + safe(() => Game.turn) + " " + J(safe(() => loadState().hostIntake, {})));
    if (n >= TURNS) { finish("turns"); return; }
    setTimeout(endTurn, 2000);
  }, 5000);
});
engine.on("GameAgeEnded", () => { emit("EVENT GameAgeEnded turn=" + safe(() => Game.turn)); finish("age ended"); });

emit("modtest74 attached control=" + CONTROL);
let beginTries = 0;
function loadStateName() { return safe(() => { const s = UI.getGameLoadingState(); for (const k of Object.keys(UIGameLoadingState)) if (UIGameLoadingState[k] === s) return k; return String(s); }, "?"); }
function beginPoll() {
  const st = loadStateName();
  if (st === "GameStarted") { setTimeout(() => { try { run(); } catch (e) { emit("run threw " + e + " " + (e && e.stack)); emit("DONE modtest74 finished"); } }, 10000); return; }
  beginTries++;
  if (st === "WaitingToStart" || st === "WaitingForUIReady" || beginTries % 5 === 0) safe(() => UI.notifyUIReady());
  if (beginTries < 90) setTimeout(beginPoll, 2000); else emit("LOAD gave up");
}
setTimeout(beginPoll, 3000);
